// Strips the attribution footer a Claude Code session leaves: from a pull request description,
// and from a comment where a session marker takes its place. Kept apart from
// `strip-claude-footer.yml` so that it can be tested (`claude-footer.test.mjs`, beside it).
//
// Imported from Reefact/conventional-comments-toolkit (`scripts/lib/claude-footer.mjs`), which
// measured why it exists:
//
// DESCRIPTIONS never keep the footer. An instruction to the session is not enough: on
// Reefact/conventional-comments-toolkit#167 the session sent a description without one and the
// pull-request creation tool added its own on the way. Editing a description through the tool
// adds none (measured on #165), so the footer can only be removed AFTER creation, by a path the
// tool takes no part in.
//
// COMMENTS lose it only when the line before it is a session marker - the `[session:...]` line
// the `review-pull-request` and `respond-to-review` skills end their comments with. The marker
// then says who wrote the comment (a session, not the account holder) and the footer repeats it.
// Without a marker nothing else would say so, and the footer stays.
//
// Three endings are recognised, all at the very end of the text, sometimes one after another:
//   - the one the session writes in a description:
//       🤖 Generated with [Claude Code](https://claude.com/claude-code)
//
//       https://claude.ai/code/session_...       (the session link is optional)
//   - the session link ALONE on the last line, without the 🤖 line: it belongs to the same
//     footer and goes with it. A session link quoted on purpose at the end of a text goes too:
//     that is the accepted price.
//   - the one the tool adds (descriptions and comments):
//       ---
//       _Generated by [Claude Code](https://claude.ai/code/session_...)_
//
// Only the END of the text is examined: the same sentence quoted in the middle (as here) stays.

const TRAILERS = [
  // The tool's form: a horizontal rule, then the italic line.
  /(?:^|\n)[ \t]*---[ \t]*\n+[ \t]*_Generated by \[Claude Code\]\([^)\s]*\)_[ \t]*$/u,
  // The session's form, with the session link if it follows.
  /(?:^|\n)[ \t]*🤖 Generated with \[Claude Code\]\([^)\s]*\)[ \t]*(?:\n+[ \t]*https:\/\/claude\.ai\/code\/session_\S+[ \t]*)?$/u,
  // A session link left alone on the last line.
  /(?:^|\n)[ \t]*https:\/\/claude\.ai\/code\/session_\S+[ \t]*$/u,
];

const TRAILING_WS = /\s+$/u;

function normalize(text) {
  return text.replace(/\r\n/g, '\n');
}

/** The text without the footers ending it, trailing whitespace removed; `null` if there are none. */
function withoutFooters(text) {
  let current = normalize(text);
  let stripped = false;
  for (;;) {
    const trimmed = current.replace(TRAILING_WS, '');
    const pattern = TRAILERS.find((candidate) => candidate.test(trimmed));
    if (!pattern) { break; }
    current = trimmed.replace(pattern, '');
    stripped = true;
  }
  return stripped ? current.replace(TRAILING_WS, '') : null;
}

/**
 * The description without the Claude Code footers ending it.
 * Returns the input string itself, untouched, when there is nothing to remove.
 * @param {string | null | undefined} body
 * @returns {string}
 */
export function stripClaudeFooter(body) {
  const original = body ?? '';
  return withoutFooters(original) ?? original;
}

// Marker recognition: a copy of the toolkit's `extractSessionMarker()` (@cct/core, §3.6), which
// a workflow cannot import without installing and building the toolkit. The toolkit's own
// parity test holds this copy to the original; the cases in `claude-footer.test.mjs` record
// what that test established.
const FENCE_RE = /^\s*(`{3,}|~{3,})/;
const QUOTE_RE = /^\s*>/;
const EDGE = /^[\p{White_Space}﻿]+|[\p{White_Space}﻿]+$/gu;
const MARKER_RE = /^\[session:(.*)\]$/u;

function strip(s) {
  return s.replace(EDGE, '');
}

/**
 * True when the last non-empty line of the text is a session marker: alone on its line, outside
 * a fenced block and a quotation, with a non-empty value.
 * @param {string} body
 * @returns {boolean}
 */
export function endsWithSessionMarker(body) {
  const lines = body.split(/\r?\n/);
  const discarded = new Set();
  let fence = null;
  for (let i = 0; i < lines.length; i++) {
    const m = FENCE_RE.exec(lines[i]);
    if (fence !== null) {
      discarded.add(i);
      if (m && m[1].startsWith(fence[0]) && m[1].length >= fence.length) { fence = null; }
      continue;
    }
    if (m) {
      fence = m[1];
      discarded.add(i);
      continue;
    }
    if (QUOTE_RE.test(lines[i])) { discarded.add(i); }
  }
  for (let i = lines.length - 1; i >= 0; i--) {
    const line = strip(lines[i]);
    if (line === '') { continue; }
    if (discarded.has(i)) { return false; }
    const m = MARKER_RE.exec(line);
    return m !== null && strip(m[1]) !== '';
  }
  return false;
}

/**
 * The comment without the Claude Code footer ending it, ONLY if what remains ends with a
 * session marker. Returns the input string untouched otherwise.
 * @param {string | null | undefined} body
 * @returns {string}
 */
export function stripClaudeFooterAfterSessionMarker(body) {
  const original = body ?? '';
  const stripped = withoutFooters(original);
  return stripped !== null && endsWithSessionMarker(stripped) ? stripped : original;
}
